package ca.teamdman.sfm.common.value;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public final class ValueFoundationProof {
    private static int checks;

    private static void require(boolean condition, String name) {
        checks++;
        if (!condition) throw new AssertionError(name);
    }

    private static void rejects(Runnable operation, String name) {
        try {
            operation.run();
        } catch (IllegalArgumentException | NullPointerException expected) {
            checks++;
            return;
        }
        throw new AssertionError("Accepted " + name);
    }

    private static void failure(SFMValueSchema schema, SFMValue value, String code, String path) {
        var result = schema.validate(value);
        require(result.isPresent(), "Expected schema failure");
        require(result.get().code().equals(code), "Schema failure code " + code);
        require(result.get().path().equals(path), "Schema failure path " + path);
    }

    public static void main(String[] ignored) {
        require(SFMValueJsonCodec.VERSION == 2, "Codec writer version");
        require(SFMValueJsonCodec.OLDEST_READABLE_VERSION == 1, "Oldest reader version");
        require(SFMValueJsonCodec.decode("9223372036854775807", 1).equals(SFMValue.of(Long.MAX_VALUE)), "v1 exact long maximum");
        require(SFMValueJsonCodec.decode("-9223372036854775808", 1).equals(SFMValue.of(Long.MIN_VALUE)), "v1 exact long minimum");
        rejects(() -> SFMValueJsonCodec.decode("1.0", 1), "v1 decimal");
        rejects(() -> SFMValueJsonCodec.decode("1e0", 1), "v1 exponent");
        rejects(() -> SFMValueJsonCodec.decode("1", 0), "codec zero");
        rejects(() -> SFMValueJsonCodec.decode("1", 3), "future codec");
        require(SFMValueJsonCodec.decode("1") instanceof SFMValue.LongValue, "Integer shape retains type");
        require(SFMValueJsonCodec.decode("1.0") instanceof SFMValue.DoubleValue, "Decimal shape retains type");
        require(SFMValueJsonCodec.decode("1e0") instanceof SFMValue.DoubleValue, "Exponent shape retains type");
        require(!SFMValue.of(1L).equals(SFMValue.of(1.0)), "Integer and double distinct");
        require(Double.doubleToRawLongBits(((SFMValue.DoubleValue) SFMValue.of(-0.0)).value()) == 0L, "Negative zero normalization");
        rejects(() -> SFMValue.of(Double.NaN), "NaN constructor");
        rejects(() -> SFMValue.of(Double.POSITIVE_INFINITY), "Positive infinity");
        rejects(() -> SFMValue.of(Double.NEGATIVE_INFINITY), "Negative infinity");
        rejects(() -> SFMValueJsonCodec.decode("1e309"), "Overflowing double");
        rejects(() -> SFMValueJsonCodec.decode("9223372036854775808"), "Overflowing integer");
        rejects(() -> SFMValueJsonCodec.decode("{\"a\":1,\"a\":2}"), "Duplicate fields");
        rejects(() -> SFMValueJsonCodec.decode("[] []"), "Trailing value");
        rejects(() -> SFMValueJsonCodec.decode("{\"a\":}"), "Malformed value");
        rejects(() -> SFMValueJsonCodec.decode("NaN"), "Non-JSON number");
        rejects(() -> SFMValue.of("\uD800"), "Lone UTF-16 surrogate");
        rejects(() -> SFMValueJsonCodec.decode("\"\\uD800\""), "Decoded lone surrogate");

        var fields = new LinkedHashMap<String, SFMValue>();
        fields.put("z", SFMValue.of("line\nnext"));
        fields.put("a", SFMValue.of(0.25));
        var value = SFMValue.object(fields);
        fields.put("new", SFMValue.of(true));
        String canonical = "{\"a\":0.25,\"z\":\"line\\nnext\"}";
        require(SFMValueJsonCodec.encode(value).equals(canonical), "Sorted canonical escaped JSON");
        require(SFMValueJsonCodec.decode(canonical).equals(value), "Canonical round trip");
        require(SFMValueJsonCodec.decode(SFMValueJsonCodec.encodePretty(value)).equals(value), "Pretty round trip");
        require(!((SFMValue.ObjectValue) value).fields().containsKey("new"), "Defensive object copy");
        try { ((SFMValue.ObjectValue) value).fields().put("x", SFMValue.of(1L)); throw new AssertionError("Mutable object"); }
        catch (UnsupportedOperationException expected) { checks++; }

        var list = new ArrayList<SFMValue>(List.of(SFMValue.of(1L)));
        var array = SFMValue.array(list);
        list.add(SFMValue.of(2L));
        require(((SFMValue.ArrayValue) array).values().size() == 1, "Defensive array copy");
        require(SFMValueJsonCodec.encode(SFMValue.of("x".repeat(3070))).length() == 3072, "Packet byte boundary");
        rejects(() -> SFMValueJsonCodec.encode(SFMValue.of("x".repeat(3071))), "Packet encode byte limit");
        rejects(() -> SFMValueJsonCodec.decode("\"" + "x".repeat(3071) + "\""), "Packet decode byte limit");
        rejects(() -> SFMValueJsonCodec.encode(SFMValue.of("é".repeat(1536))), "UTF-8 multibyte bound");
        require(SFMValueJsonCodec.decode("[".repeat(16) + "0" + "]".repeat(16)) != null, "Depth boundary");
        rejects(() -> SFMValueJsonCodec.decode("[".repeat(17) + "0" + "]".repeat(17)), "Depth limit");
        require(SFMValueJsonCodec.decode("[" + "0,".repeat(255) + "0]") != null, "Container boundary");
        rejects(() -> SFMValueJsonCodec.decode("[" + "0,".repeat(256) + "0]"), "Container limit");
        rejects(() -> SFMValueJsonCodec.encode(SFMValue.array(java.util.Collections.nCopies(257, SFMValue.of(0L)))), "Encode container limit");

        var pattern = new SFMValuePattern.ObjectPattern(Map.of("a", new SFMValuePattern.LiteralPattern(SFMValue.of(0.25))));
        require(pattern.match(value).orElseThrow().value().equals(value), "Open pattern retains full value");
        require(pattern.match(value).orElseThrow().bindings().isEmpty(), "No invented pattern bindings");
        require(pattern.match(SFMValue.object(Map.of())).isEmpty(), "Pattern missing field");
        require(SFMValuePattern.GUID.matches(SFMValue.of("AAAAAAAA-BBBB-CCCC-DDDD-EEEEEEEEEEEE")), "Canonical case-insensitive UUID");
        require(!SFMValuePattern.GUID.matches(SFMValue.of("1-1-1-1-1")), "Noncanonical UUID rejected");

        var schema = SFMValueSchema.object(Map.of(
                "u", SFMValueSchema.Field.required(SFMValueSchema.floating(0.0, 1.0)),
                "note", SFMValueSchema.Field.optional(SFMValueSchema.string(0, 32))
        ), false);
        require(schema.validate(SFMValue.object(Map.of("u", SFMValue.of(0.731)))).isEmpty(), "Touch double schema");
        failure(schema, SFMValue.object(Map.of("u", SFMValue.of(1L))), "wrong_type", "/u");
        failure(schema, SFMValue.object(Map.of("u", SFMValue.of(1.1))), "out_of_range", "/u");
        failure(schema, SFMValue.object(Map.of()), "missing_field", "/u");
        failure(schema, SFMValue.object(Map.of("u", SFMValue.of(0.2), "x", SFMValue.of(true))), "extra_field", "/x");
        var pointer = SFMValueSchema.object(Map.of("a~/b", SFMValueSchema.Field.required(SFMValueSchema.bool())), false);
        failure(pointer, SFMValue.object(Map.of("a~/b", SFMValue.of(1L))), "wrong_type", "/a~0~1b");
        require(SFMValueSchema.optional(SFMValueSchema.bool()).validate(SFMValue.nullValue()).isEmpty(), "Explicit optional null");
        require(SFMValueSchema.integer(Long.MIN_VALUE, Long.MAX_VALUE).validate(SFMValue.of(Long.MAX_VALUE)).isEmpty(), "Schema exact long range");
        require(SFMValueSchema.number(BigDecimal.ZERO, BigDecimal.ONE).validate(SFMValue.of(0.5)).isEmpty(), "Either numeric variant");
        failure(SFMValueSchema.array(SFMValueSchema.bool(), 1, 3), SFMValue.array(List.of(SFMValue.of(1L))), "wrong_type", "/0");
        failure(SFMValueSchema.union(List.of(SFMValueSchema.bool(), SFMValueSchema.nil())), SFMValue.of(1L), "no_union_match", "");
        String action = SFMValueSchema.canonicalActionJson(SFMValue.of("x".repeat(4096)));
        require(SFMValueSchema.decodeActionJson(action).equals(SFMValue.of("x".repeat(4096))), "Larger bounded action envelope");
        rejects(() -> SFMValueSchema.canonicalActionJson(SFMValue.of("x".repeat(16383))), "Action envelope bound");
        failure(SFMValueSchema.any(), SFMValue.array(java.util.Collections.nCopies(257, SFMValue.of(0L))), "value_out_of_bounds", "");
        System.out.println("value-foundation-proof checks=" + checks + " status=passed");
    }
}
